export default function build({ THREE, kit, traits, ui, hands }) {
  const root = new THREE.Group();
  root.name = 'Voxel Valley Defense';
  const W = 0.46, D = 0.35, floor = 0.035;
  const mat = {
    frame: kit.material('paintedMetal', { color: '#253747', wear: 0.24 }),
    brass: kit.material('brass', { color: '#cba35b' }),
    grass: kit.material('grass', { colors: ['#335846', '#57815a'] }),
    road: kit.material('stone', { colors: ['#75868b', '#a1afa8'] }),
    stone: kit.material('stone', { color: '#465b67' }),
    blue: kit.material('paintedMetal', { color: '#53bbc9', wear: 0.15 }),
    dark: kit.material('rubber', { color: '#1b2936' }),
    glow: kit.material('light', { color: '#a2f9e1', glow: 1.8 }),
    orange: kit.material('paintedMetal', { color: '#e89459', wear: 0.18 }),
    monster: kit.material('paintedMetal', { color: '#b57ed1', wear: 0.12 }),
    eye: kit.material('light', { color: '#ffcf79', glow: 2 }),
    wood: kit.material('wood', { color: '#654c3c' })
  };
  // Crisp, low-poly cubes are intentional: every creature and tower is voxel-built.
  const cube = new THREE.BoxGeometry(1, 1, 1);
  function mesh(g, m, x, y, z, parent = root) {
    const o = new THREE.Mesh(g, m);
    o.position.set(x, y, z);
    parent.add(o);
    return o;
  }
  function block(parent, x, y, z, w, h, d, m) {
    const o = mesh(cube, m, x, y, z, parent);
    o.scale.set(w, h, d);
    return o;
  }
  root.add(kit.shadow(0.29, 0.35));
  mesh(kit.roundedBox(W, 0.026, D, 0.006), mat.frame, 0, 0.013, 0);
  block(root, 0, 0.029, 0, W - 0.012, 0.012, D - 0.012, mat.grass);
  const trim = new THREE.Group();
  for (const x of [-1, 1]) block(trim, x * 0.226, 0.031, 0, 0.004, 0.01, D - 0.008, mat.brass);
  for (const z of [-1, 1]) block(trim, 0, 0.031, z * 0.171, W - 0.008, 0.01, 0.004, mat.brass);
  const screws = [];
  for (const x of [-0.217, 0.217]) for (const z of [-0.162, 0.162]) screws.push([x, 0.038, z]);
  trim.add(kit.instances(new THREE.CylinderGeometry(0.002, 0.002, 0.002, 8), mat.brass, screws));
  root.add(kit.merge(trim));

  const path = [[-0.211, -0.105], [0.14, -0.105], [0.14, 0], [-0.14, 0], [-0.14, 0.105], [0.211, 0.105]];
  const lengths = [], starts = [];
  let total = 0;
  const pavers = [], edges = [];
  for (let i = 0; i < path.length - 1; i++) {
    const a = path[i], b = path[i + 1], dx = b[0] - a[0], dz = b[1] - a[1];
    const len = Math.hypot(dx, dz), n = Math.ceil(len / 0.013);
    starts.push(total);
    lengths.push(len);
    total += len;
    for (let j = 0; j <= n; j++) {
      const f = j / n, x = a[0] + dx * f, z = a[1] + dz * f;
      pavers.push({
        position: [x, floor + 0.001, z],
        rotation: [0, dx === 0 ? Math.PI / 2 : 0, 0],
        scale: [1, 1, 1]
      });
      for (const side of [-1, 1])
        edges.push([x - dz / len * 0.02 * side, floor + 0.003, z + dx / len * 0.02 * side]);
    }
  }
  root.add(kit.instances(new THREE.BoxGeometry(0.012, 0.004, 0.029), mat.road, pavers));
  root.add(kit.instances(new THREE.BoxGeometry(0.006, 0.006, 0.006), mat.stone, edges));

  const scenery = new THREE.Group();
  for (const [x, z, s] of [[-0.195, 0.045, 1], [0.192, -0.06, 0.8], [-0.19, -0.15, 0.7], [0.19, -0.145, 1], [0.02, 0.145, 0.8]]) {
    block(scenery, x, floor + 0.009 * s, z, 0.008 * s, 0.018 * s, 0.008 * s, mat.wood);
    block(scenery, x, floor + 0.025 * s, z, 0.024 * s, 0.021 * s, 0.024 * s, mat.grass);
    block(scenery, x, floor + 0.039 * s, z, 0.015 * s, 0.012 * s, 0.015 * s, mat.grass);
  }
  block(scenery, 0.206, floor + 0.017, 0.105, 0.03, 0.034, 0.048, mat.stone);
  block(scenery, 0.19, floor + 0.018, 0.105, 0.004, 0.025, 0.024, mat.glow);
  for (const z of [0.085, 0.125])
    block(scenery, 0.206, floor + 0.039, z, 0.033, 0.012, 0.009, mat.brass);
  root.add(kit.merge(scenery));

  const sites = [[-0.125, -0.151], [-0.045, -0.052], [0.08, -0.052], [-0.07, 0.052], [0.065, 0.052], [0.12, 0.151]];
  const pads = [], enemies = [];
  let mode = 'demo', coins = 75, lives = 6, wave = 1, spawned = 0;
  let spawnClock = 0, waveWait = 0, paused = false, hovered = -1;
  let panel;
  const aim = new THREE.Vector3(), up = new THREE.Vector3(0, 1, 0);
  const beamGeo = new THREE.CylinderGeometry(0.0018, 0.0018, 1, 6);

  for (let i = 0; i < sites.length; i++) {
    const [x, z] = sites[i], tower = new THREE.Group();
    tower.position.set(x, floor + 0.006, z);
    tower.name = 'Voxel tower ' + (i + 1);
    const foot = new THREE.Group();
    block(foot, 0, 0.006, 0, 0.035, 0.012, 0.035, mat.stone);
    block(foot, 0, 0.018, 0, 0.025, 0.019, 0.025, mat.blue);
    for (const a of [-1, 1]) for (const b of [-1, 1])
      block(foot, a * 0.014, 0.015, b * 0.014, 0.007, 0.025, 0.007, mat.brass);
    tower.add(kit.merge(foot));
    const head = new THREE.Group();
    block(head, 0, 0, 0, 0.032, 0.02, 0.027, mat.blue);
    block(head, 0, 0, 0.021, 0.012, 0.011, 0.029, mat.dark);
    block(head, 0, 0, 0.036, 0.014, 0.013, 0.005, mat.glow);
    for (const s of [-1, 1])
      block(head, s * 0.019, 0.004, 0, 0.006, 0.013, 0.022, mat.brass);
    const turret = kit.merge(head);
    turret.position.y = 0.038;
    tower.add(turret);
    root.add(tower);
    const pad = mesh(kit.roundedBox(0.043, 0.006, 0.043, 0.002), mat.stone, x, floor + 0.003, z);
    pad.name = 'Build or upgrade tower ' + (i + 1);
    const ringMat = kit.material('light', { color: '#65d3d3', glow: 0.6 });
    const rim = mesh(new THREE.TorusGeometry(0.022, 0.0012, 4, 24), ringMat, x, floor + 0.007, z);
    rim.rotation.x = Math.PI / 2;
    const beam = mesh(beamGeo, mat.glow, 0, 0, 0);
    beam.visible = false;
    const flash = kit.glow('#a2f9e1', 0.04, { opacity: 0.7 });
    root.add(flash);
    flash.visible = false;
    pads.push({ x, z, tower, head: turret, ringMat, level: 0, cooldown: 0, beam, flash, flashTime: 0 });
    traits(pad, { onPress() { buildTower(i); } });
    traits(tower, { onPress() { buildTower(i); } });
  }

  for (let i = 0; i < 12; i++) {
    const model = new THREE.Group();
    block(model, 0, 0.017, 0, 0.024, 0.021, 0.022, mat.monster);
    block(model, 0, 0.033, 0, 0.03, 0.017, 0.025, mat.monster);
    for (const s of [-1, 1]) {
      block(model, s * 0.01, 0.004, 0, 0.009, 0.008, 0.015, mat.dark);
      block(model, s * 0.018, 0.017, 0, 0.008, 0.018, 0.01, mat.monster);
      block(model, s * 0.008, 0.035, 0.013, 0.006, 0.005, 0.002, mat.eye);
      block(model, s * 0.011, 0.044, 0, 0.006, 0.009, 0.008, mat.dark);
    }
    block(model, 0, 0.028, 0.013, 0.01, 0.003, 0.002, mat.dark);
    const g = kit.merge(model);
    g.name = 'Voxel monster';
    g.visible = false;
    root.add(g);
    enemies.push({ g, active: false, distance: 0, hp: 4, phase: i * 1.7 });
  }

  const startPiece = new THREE.Group();
  startPiece.name = 'START';
  startPiece.position.set(-0.13, floor, 0.153);
  block(startPiece, 0, 0.005, 0, 0.085, 0.01, 0.035, mat.brass);
  const key = mesh(kit.roundedBox(0.078, 0.012, 0.031, 0.003), mat.orange, 0, 0.014, 0, startPiece);
  const label = kit.card('START', { width: 0.065 });
  label.rotation.x = -Math.PI / 2;
  label.position.y = 0.021;
  startPiece.add(label);
  root.add(startPiece);
  traits(startPiece, { onPress: start });

  const cursor = kit.ring(0.008, 0.011, { colors: ['#a2f9e1', '#a2f9e1'], opacity: 0.85 });
  root.add(cursor);
  cursor.visible = false;

  function hud(message, tone = 'neutral') {
    panel.set('score', coins + ' gold | ' + lives + ' lives');
    panel.set('wave', (Math.min(wave, 3) - 1 + Math.min(1, spawned / (4 + wave * 2))) / 3, 'Wave ' + Math.min(wave, 3) + ' / 3');
    if (message) panel.set('state', message, tone);
  }
  function start() {
    mode = 'play'; coins = 75; lives = 6; wave = 1;
    spawned = 0; spawnClock = 0.5; waveWait = 0; paused = false;
    for (const e of enemies) { e.active = false; e.g.visible = false; }
    for (let i = 0; i < pads.length; i++) {
      const p = pads[i];
      p.level = i === 1 ? 1 : 0;
      p.cooldown = 0;
      p.tower.visible = !!p.level;
      p.tower.scale.setScalar(1);
      p.flashTime = 0;
      p.beam.visible = false;
      p.flash.visible = false;
    }
    panel.set('start', 'Play again');
    panel.set('pause', 'Pause');
    hud('Build towers on the glowing pads.', 'good');
  }
  function buildTower(i) {
    if (mode !== 'play') start();
    if (paused) return;
    const p = pads[i], cost = p.level ? 30 : 25;
    p.flashTime = 0.2;
    p.flash.position.set(p.x, floor + 0.06, p.z);
    p.flash.visible = true;
    if (p.level >= 3) { hud('This tower is fully upgraded.'); return; }
    if (coins < cost) { hud('Need ' + cost + ' gold.', 'poor'); return; }
    coins -= cost;
    p.level++;
    p.tower.visible = true;
    p.tower.scale.setScalar(1 + (p.level - 1) * 0.12);
    hud(p.level === 1 ? 'Tower built! Upgrades cost 30 gold.' : 'Upgraded to level ' + p.level + '!', 'good');
  }
  function finish(win) {
    mode = 'end';
    hud(win ? 'Victory! The crystal is safe.' : 'Defeat! The vault was overrun.', win ? 'good' : 'bad');
    panel.set('start', 'Play again');
  }
  panel = kit.panel(ui, {
    width: 0.38, position: [0, 0.31, -0.215], rotationY: 0,
    title: 'Voxel Valley',
    items: [
      { text: 'Move a hand over a pad and pinch to build or upgrade.' },
      { stat: '75 gold | 6 lives', label: 'Build 25 - Upgrade 30', id: 'score' },
      { progress: 0, label: 'Defend all 3 waves', id: 'wave' },
      { status: 'Press START to defend the crystal.', id: 'state', tone: 'neutral' },
      { buttons: [
        { label: 'Start', id: 'start', onPress: start },
        { label: 'Pause', id: 'pause', onPress() {
          if (mode !== 'play') return;
          paused = !paused;
          panel.set('pause', paused ? 'Resume' : 'Pause');
          hud(paused ? 'Paused' : 'Defend the crystal!');
        } }
      ] }
    ]
  });
  root.add(panel.object3D);
  for (let i = 0; i < pads.length; i++) {
    pads[i].level = i === 1 || i === 4 ? 1 : 0;
    pads[i].tower.visible = !!pads[i].level;
  }

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, 0.05);
      const hand = hands.right.tracked ? hands.right : hands.left.tracked ? hands.left : null;
      hovered = -1;
      if (hand && mode !== 'end') {
        let best = 0.035;
        for (let i = 0; i < pads.length; i++) {
          const p = pads[i], d = Math.hypot(hand.tip.x - p.x, hand.tip.z - p.z);
          if (d < best && hand.tip.y < floor + 0.24) { best = d; hovered = i; }
        }
        cursor.visible = hovered >= 0;
        if (hovered >= 0) {
          const p = pads[hovered];
          cursor.position.set(p.x, floor + 0.009, p.z);
          if (hand.pinched) buildTower(hovered);
        }
      } else cursor.visible = false;
      key.position.y = 0.014 + Math.sin(time * 3) * 0.001;
      for (let i = 0; i < pads.length; i++) {
        const p = pads[i];
        p.ringMat.emissiveIntensity = i === hovered ? 2.5 : 0.5 + Math.sin(time * 2 + i) * 0.2;
        p.flashTime -= dt;
        p.flash.visible = p.flashTime > 0;
        if (p.flashTime <= 0) p.beam.visible = false;
      }
      if (paused || mode === 'end') return;
      const demo = mode === 'demo', count = 4 + wave * 2;
      spawnClock -= dt;
      if ((demo || spawned < count) && spawnClock <= 0) {
        let available = null;
        for (const e of enemies) if (!e.active) { available = e; break; }
        if (available) {
          available.active = true;
          available.g.visible = true;
          available.distance = 0;
          available.hp = demo ? 4 : 3 + wave;
          spawned++;
          spawnClock = demo ? 2.2 : 1.65 - wave * 0.12;
          if (!demo) hud();
        }
      }
      for (const e of enemies) {
        if (!e.active) continue;
        e.distance += dt * (demo ? 0.047 : 0.043 + wave * 0.007);
        if (e.distance >= total) {
          e.active = false;
          e.g.visible = false;
          if (!demo) {
            lives--;
            hud('A monster reached the vault!', 'bad');
            if (lives <= 0) { finish(false); return; }
          }
          continue;
        }
        let segment = 0;
        while (segment < lengths.length - 1 && e.distance > starts[segment] + lengths[segment]) segment++;
        const a = path[segment], b = path[segment + 1];
        const f = (e.distance - starts[segment]) / lengths[segment];
        e.g.position.set(a[0] + (b[0] - a[0]) * f, floor + 0.004 + Math.abs(Math.sin(time * 9 + e.phase)) * 0.003, a[1] + (b[1] - a[1]) * f);
        e.g.rotation.y = Math.atan2(b[0] - a[0], b[1] - a[1]);
      }
      for (const p of pads) {
        if (!p.level) continue;
        p.cooldown -= dt;
        let target = null, furthest = -1;
        for (const e of enemies) {
          if (e.active && Math.hypot(e.g.position.x - p.x, e.g.position.z - p.z) < 0.117 + p.level * 0.009 && e.distance > furthest) {
            target = e;
            furthest = e.distance;
          }
        }
        if (!target) { p.head.rotation.y += dt * 0.35; continue; }
        p.head.rotation.y = Math.atan2(target.g.position.x - p.x, target.g.position.z - p.z);
        if (p.cooldown > 0) continue;
        p.cooldown = 0.7 - p.level * 0.09;
        const sy = floor + 0.045, ey = target.g.position.y + 0.023;
        aim.set(target.g.position.x - p.x, ey - sy, target.g.position.z - p.z);
        const len = aim.length();
        p.beam.position.set(p.x + aim.x / 2, sy + aim.y / 2, p.z + aim.z / 2);
        p.beam.quaternion.setFromUnitVectors(up, aim.normalize());
        p.beam.scale.y = len;
        p.flash.position.copy(target.g.position);
        p.flash.position.y += 0.026;
        p.flashTime = 0.1;
        p.beam.visible = true;
        p.flash.visible = true;
        target.hp -= p.level;
        if (target.hp <= 0) {
          target.active = false;
          target.g.visible = false;
          if (!demo) { coins += 10; hud('Monster defeated! +10 gold', 'good'); }
        }
      }
      let anyAlive = false;
      for (const e of enemies) if (e.active) { anyAlive = true; break; }
      if (!demo && spawned >= count && !anyAlive) {
        waveWait += dt;
        if (waveWait > 2) {
          if (wave === 3) { finish(true); return; }
          wave++;
          spawned = 0;
          spawnClock = 1.4;
          waveWait = 0;
          coins += 20;
          hud('Wave ' + wave + '! +20 gold for reinforcements.', 'good');
        }
      }
    }
  };
}
